// src/components/About.tsx

import React from 'react';

const About: React.FC = () => {
  return (
    <section style={styles.section}>
      <h2 style={styles.title}>About Me</h2>
      <p style={styles.text}>
        Hi! I'm Royce, and I'm currently in the middle of making this website! Hang tight!
      </p>
    </section>
  );
};

const styles = {
  section: {
    padding: '4rem 2rem',
    backgroundColor: '#202231',
    textAlign: 'center' as const,
  },
  title: {
    fontSize: '2.5rem',
    marginBottom: '2rem',
    color: '#333',
  },
  text: {
    fontSize: '1.2rem',
    color: '#555',
    maxWidth: '600px',
    margin: '0 auto 1.5rem',
    lineHeight: '1.6',
  },
};

export default About;
