import React from 'react';
import './styles/App.css';
import About from './components/About';
import ParticlesBackground from "./components/ParticlesBackground";

function App() {
  return (
    <div className="app-container" style={{ position: "relative", overflow: "hidden", backgroundColor: "#101211", minHeight: "100vh" }}>
      {/* Background particles */}
      <ParticlesBackground />

      {/* Foreground content */}
      <div style={{ position: "relative", zIndex: 1, ...styles.container } as React.CSSProperties}>
        <header style={styles.header}>
          <h1 style={styles.title}>Royce Mettler</h1>
          <p style={styles.subtitle}>Cool Thing 1 | Cool Thing 2 | Cool Thing 3</p>
          <a href="mailto:roycemettler@gmail.com" style={styles.button}>Contact Me</a>
        </header>

        {/* About Section */}
        <About />
      </div>
    </div>
  );
}

const styles = {
  container: {
    textAlign: 'center' as const,
    padding: '2rem',
    fontFamily: 'Arial, sans-serif',
    // Removed backgroundColor to let particles show through
  },
  header: {
    marginTop: '10vh'
  },
  title: {
    fontSize: '3rem',
    marginBottom: '1rem',
    color: '#fff' // Changed to white for better visibility on dark background
  },
  subtitle: {
    fontSize: '1.5rem',
    marginBottom: '2rem',
    color: '#ccc' // Changed to light gray for better visibility
  },
  button: {
    display: 'inline-block',
    padding: '0.75rem 1.5rem',
    backgroundColor: '#007acc',
    color: '#fff',
    borderRadius: '8px',
    textDecoration: 'none',
    fontSize: '1rem'
  }
};

export default App;